print(two_sum(nums, 18))
print(two_sum(nums, 26))

def reverse_string(s):
    return s[::-1]

def reverse_words(s):
    return ' '.join(s.split()[::-1])

def reverse_each_word(s):
    return ' '.join(word[::-1] for word in s.split())

